// What we know about stock ZMK: the keycode/parameter macros from its
// dt-bindings headers (vendored in zmk-defines.json) and its built-in
// behaviors (from app/dts/behaviors/*.dtsi).

import ZmkDefinesJson from "./zmk-defines.json";
import { MacroTable, preprocess } from "./preprocessor";

// Generated by scripts/generate-zmk-defines.ts.
interface ZmkDefinesData {
  source: string;
  keycodes: [string, number][];
  deprecatedKeycodes: [string, number][];
  // header file -> [name, cells]
  constants: Record<string, [string, number[]][]>;
  functionMacros: string[];
}

const ZmkDefines = ZmkDefinesJson as unknown as ZmkDefinesData;

export type ParamKind = "hid" | "layer" | "value";

export interface BuiltinBehavior {
  // devicetree label, as written after `&` in a keymap
  label: string;
  // display-name(s) the firmware reports over the Studio RPC. Behaviors
  // without a display-name report their node name instead.
  displayNames: string[];
  cells: number;
  // What each cell means, used when the device gives us no metadata.
  params: ParamKind[];
  // Header whose constants name this behavior's parameters, and which of
  // its names apply (pointing.h is shared by three behaviors).
  constantsHeader?: string;
  constantsMatch?: RegExp;
}

