const normalize = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");

export function builtinByLabel(label: string): BuiltinBehavior | undefined {
  return BUILTIN_BEHAVIORS.find((b) => b.label === label);
}

export function builtinByDisplayName(name: string): BuiltinBehavior | undefined {
  const n = normalize(name);
  return BUILTIN_BEHAVIORS.find((b) => b.displayNames.some((d) => normalize(d) === n));
}

// Turn an arbitrary display name into something usable as a devicetree label.
export function toLabel(name: string): string {
  const label = name
    .toLowerCase()
    .replace(/[^a-z0-9_]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return /^[a-z_]/.test(label) ? label : `b_${label}`;
}

export function labelsMatch(label: string, displayName: string): boolean {
  return normalize(label) === normalize(displayName);
}

// ---------------------------------------------------------------------------
// Macros available to every keymap without an #include, as if the standard
// ZMK headers had been included.

let builtinMacros: MacroTable | undefined;

export function zmkMacros(): MacroTable {
  if (!builtinMacros) {
    const lines = [...ZmkDefines.functionMacros];
    for (const [name, value] of [...ZmkDefines.keycodes, ...ZmkDefines.deprecatedKeycodes]) {
      lines.push(`#define ${name} ${value}`);
    }
    for (const entries of Object.values(ZmkDefines.constants)) {
      for (const [name, cells] of entries) {
        lines.push(`#define ${name} ${cells.join(" ")}`);
      }
    }
    builtinMacros = preprocess(lines.join("\n")).macros;
  }
  return builtinMacros;
}

