// ---------------------------------------------------------------------------
// Value -> name, for export.

const MODIFIER_FUNCTIONS = ["LC", "LS", "LA", "LG", "RC", "RS", "RA", "RG"];

let keycodeNames: Map<number, string> | undefined;

function preferredKeycodeNames(): Map<number, string> {
  if (!keycodeNames) {
    // Several names share a value (N1/NUMBER_1, RET/ENTER/RETURN...). Use the
    // shortest non-deprecated one; ties go to the one ZMK defines first.
    keycodeNames = new Map();
    for (const [name, value] of ZmkDefines.keycodes) {
      const existing = keycodeNames.get(value);
      if (!existing || name.length < existing.length) {
        keycodeNames.set(value, name);
      }
    }
  }
  return keycodeNames;
}

// Format a HID usage (possibly carrying implicit modifiers in the top byte) as
// a ZMK keycode expression such as `A`, `EXCL` or `LC(LS(T))`.
export function keycodeName(value: number): string | undefined {
  const names = preferredKeycodeNames();
  const direct = names.get(value >>> 0);
  if (direct) return direct;

  const mods = (value >>> 24) & 0xff;
  const base = names.get(value & 0x00ffffff);
  if (!base || !mods) return undefined;

  let expr = base;
  for (let bit = 7; bit >= 0; bit--) {
    if (mods & (1 << bit)) expr = `${MODIFIER_FUNCTIONS[bit]}(${expr})`;
  }
  return expr;
}

export function constantsFor(behavior: BuiltinBehavior): [string, number[]][] {
  if (!behavior.constantsHeader) return [];
  return (ZmkDefines.constants[behavior.constantsHeader] || []).filter(
    ([name]) =>
      !name.endsWith("_CMD") &&
      !name.startsWith("ZMK_") &&
      (!behavior.constantsMatch || behavior.constantsMatch.test(name))
  );
}

export const zmkDefinesSource = ZmkDefines.source;
